$('appUpdate').onclick=async()=>{const b=$('appUpdate'),s=$('updateStatus');b.disabled=true;let timer,listener;try{if(!navigator.onLine)throw Error('インターネットに接続してください');if(!('serviceWorker' in navigator)||!navigator.serviceWorker.controller)throw Error('公開サイトでオンライン起動し、再読み込みしてからお試しください');const reg=await navigator.serviceWorker.getRegistration();if(!reg)throw Error('オフライン機能が未登録です');s.textContent='最新版を確認中…';const old=navigator.serviceWorker.controller;let changed=false;const activation=new Promise(resolve=>{listener=()=>{if(navigator.serviceWorker.controller!==old){changed=true;resolve(true)}};navigator.serviceWorker.addEventListener('controllerchange',listener);timer=setTimeout(()=>resolve(false),30000)});await reg.update();if(reg.waiting)reg.waiting.postMessage({type:'SKIP_WAITING'});if(changed||reg.installing||reg.waiting||reg.active!==old){s.textContent='更新を適用中…';if(!changed&&!await activation)throw Error('更新の適用待ちです。再度お試しください');location.reload();return} s.textContent='最新版です（公開済みの更新はありません）';}catch(e){s.textContent='更新できません：'+e.message;}finally{clearTimeout(timer);if(listener)navigator.serviceWorker.removeEventListener('controllerchange',listener);b.disabled=false;}};

